&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;Commuter and Flexible Spending Programs &lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40,&amp;quot;335559991&amp;quot;:446,&amp;quot;469777462&amp;quot;:[720,630],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;On&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;-site&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;5 days a week&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;for&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;the first&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;3 to 6 months&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;&amp;nbsp;then&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;&amp;nbsp;4 days in&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;the&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;office&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;and&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;&amp;nbsp;1 day remote&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;&amp;nbsp;thereafter&lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40,&amp;quot;335559991&amp;quot;:446,&amp;quot;469777462&amp;quot;:[720,630],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
